import{_ as i,o as a,c as t,ae as n}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"ADR 026: Dynamic Industry Validation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/026-dynamic-industry-validation.md","filePath":"adr/026-dynamic-industry-validation.md"}'),o={name:"adr/026-dynamic-industry-validation.md"};function s(r,e,d,l,c,u){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-026-dynamic-industry-validation" tabindex="-1">ADR 026: Dynamic Industry Validation <a class="header-anchor" href="#adr-026-dynamic-industry-validation" aria-label="Permalink to &quot;ADR 026: Dynamic Industry Validation&quot;">​</a></h1><ul><li>Status: accepted</li><li>Deciders: Elena, Antigravity</li><li>Date: 2026-03-04</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>Initially, the tender scope validation was hardcoded for &quot;Digital Services&quot; with a fixed set of positive/negative keywords. This made it difficult to adapt the system for other industries (e.g., Construction, Healthcare) without changing the source code.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li>Extensibility: Support multiple industries without code changes.</li><li>Data-Driven Design: Manage validation criteria via database presets.</li><li>Fallback Resilience: Maintain a default &quot;Digital Services&quot; check if no industry is specified or database fails.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ol><li><strong>Hardcoded Switch Case</strong>: Easy to implement but requires code changes for ogni new industry.</li><li><strong>Configuration File (JSON)</strong>: Better, but still requires a redeploy to add new industries.</li><li><strong>Database-Driven Factory (Chosen)</strong>: Store industry keywords in a table and use a Factory pattern to instantiate rules at runtime.</li></ol><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>Database-Driven Factory</strong>, because it provides the highest flexibility for end-users to define new validation templates directly in the database.</p><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li>New industries can be added via simple SQL inserts.</li><li>The <code>ScopeValidationRule</code> is now a generic, reusable component.</li><li>Supports a default fallback to ensure the system remains functional if data is missing.</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li>Adds a database dependency to the validation flow (mitigated by caching/fallbacks).</li><li>Minor performance overhead due to database lookup (mitigated by singleton DB connection).</li></ul>',14)])])}const p=i(o,[["render",s]]);export{m as __pageData,p as default};
